import { chromium } from 'playwright';
import { spawn } from 'node:child_process';

const server = spawn('node', ['harness/server.mjs', '--port', '4188'], { stdio: ['ignore', 'ignore', 'inherit'] });
await new Promise((r) => setTimeout(r, 900));

const browser = await chromium.launch();
const page = await browser.newPage();
const base = 'http://127.0.0.1:4188/';
const out = [];
const ok = (name, cond, extra = '') => out.push(`${cond ? 'PASS' : 'FAIL'}  ${name}${extra ? ' :: ' + extra : ''}`);

page.on('pageerror', (e) => out.push(`FAIL  pageerror :: ${e.message}`));

// 1. seed + newest-first
await page.goto(base);
await page.waitForSelector('.note');
const ids = await page.$$eval('.note', (ns) => ns.map((n) => n.getAttribute('data-note-id')));
